import json
for f in ['real_runs_v16/simplify_P11.json','real_runs_v16/simplify_P02.json']:
    d=json.load(open(f));print(f)
    for t in d['session']['result']['trace']:
        m=t['move']
        if t['actor']=='buyer':
            for s in m.get('term_sheets',[])[:1]: print(' B',t['round'],s['terms']); 
            print('   body',m.get('body','')[:300].replace('\n',' '))
        else: print(' S',t['round'],m.get('status'),m['terms'],m.get('text','')[:260].replace('\n',' '))
